<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Accessibility is a strength. Curation is a requirement.</title>
  <style>
    /* Reset & Base Setup */
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }
    body {
      width: 1920px;
      height: 1080px;
      overflow: hidden;
      background-color: #ffffff;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      position: relative;
      color: #0B192C; /* Deep Navy */
    }

    /* Background Template */
    .shell {
      position: absolute;
      top: 0;
      left: 0;
      width: 1920px;
      height: 1080px;
      z-index: 0;
      pointer-events: none;
    }

    /* Content Container */
    .content-area {
      position: absolute;
      top: 0;
      left: 0;
      width: 1920px;
      height: 1080px;
      z-index: 1;
      padding: 120px 140px 200px 140px; /* Leave room for footer */
      display: flex;
      flex-direction: column;
    }

    /* Typography */
    h1 {
      font-size: 64px;
      font-weight: 800;
      line-height: 1.1;
      letter-spacing: -0.02em;
      color: #0B192C;
      margin-bottom: 24px;
    }
    h2 {
      font-size: 36px;
      font-weight: 400;
      line-height: 1.3;
      color: #4A5568;
      margin-bottom: 80px;
      max-width: 1400px;
    }
    .citations {
      font-size: 20px;
      color: #718096;
      vertical-align: super;
      margin-left: 8px;
      font-weight: 500;
    }

    /* Main Visual Area */
    .visual-container {
      flex: 1;
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      width: 100%;
    }

    /* Signal vs Noise Diagram */
    .diagram {
      width: 100%;
      max-width: 1400px;
      height: 400px;
      position: relative;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    /* SVG Layer */
    .svg-layer {
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      z-index: 1;
    }

    /* Labels */
    .label-group {
      position: relative;
      z-index: 2;
      display: flex;
      flex-direction: column;
      align-items: center;
      width: 300px;
    }
    .label-group.left {
      align-items: flex-start;
    }
    .label-group.right {
      align-items: flex-end;
    }
    .label-title {
      font-size: 28px;
      font-weight: 700;
      color: #0B192C;
      margin-bottom: 12px;
      text-transform: uppercase;
      letter-spacing: 0.05em;
    }
    .label-desc {
      font-size: 22px;
      color: #4A5568;
      line-height: 1.4;
    }
    .label-group.left .label-desc {
      text-align: left;
    }
    .label-group.right .label-desc {
      text-align: right;
    }

    /* Curation Box */
    .curation-box {
      position: absolute;
      left: 50%;
      top: 50%;
      transform: translate(-50%, -50%);
      width: 240px;
      height: 320px;
      border: 2px dashed #0055A4; /* SAEM Blue */
      border-radius: 12px;
      background-color: rgba(255, 255, 255, 0.9);
      z-index: 3;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 24px;
      box-shadow: 0 10px 30px rgba(11, 25, 44, 0.05);
    }
    .curation-title {
      font-size: 24px;
      font-weight: 700;
      color: #0055A4;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      margin-bottom: 8px;
    }
    .curation-desc {
      font-size: 18px;
      color: #4A5568;
      text-align: center;
      line-height: 1.3;
    }

  </style>
</head>
<body>

  <!-- Background Template -->
  <img class="shell" src="../../../../templates/saem-annual-meeting-template-v1/template.png" alt="" aria-hidden="true" />

  <!-- Content Area -->
  <div class="content-area">

    <!-- Header -->
    <header>
      <h1>Accessibility is a strength. Curation is a requirement.</h1>
      <h2>Open access is useful. Quality still needs judgment.<span class="citations">[5, 15, 29]</span></h2>
    </header>

    <!-- Visual -->
    <div class="visual-container">
      <div class="diagram">

        <!-- SVG Connections & Particles -->
        <svg class="svg-layer" viewBox="0 0 1400 400" preserveAspectRatio="xMidYMid meet">
          <!-- Definitions -->
          <defs>
            <linearGradient id="fadeRight" x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stop-color="#E2E8F0" stop-opacity="1" />
              <stop offset="100%" stop-color="#E2E8F0" stop-opacity="0" />
            </linearGradient>
            <linearGradient id="fadeLeft" x1="100%" y1="0%" x2="0%" y2="0%">
              <stop offset="0%" stop-color="#E2E8F0" stop-opacity="1" />
              <stop offset="100%" stop-color="#E2E8F0" stop-opacity="0" />
            </linearGradient>
            <filter id="blurFilter" x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur stdDeviation="4" />
            </filter>
          </defs>

          <!-- NOISE (Left Side) - Chaotic, scattered, varying opacities -->
          <g transform="translate(0, 0)">
            <!-- Lines -->
            <line x1="300" y1="80" x2="580" y2="150" stroke="#CBD5E0" stroke-width="2" stroke-dasharray="4 4" />
            <line x1="300" y1="150" x2="580" y2="180" stroke="#CBD5E0" stroke-width="1" />
            <line x1="300" y1="220" x2="580" y2="200" stroke="#CBD5E0" stroke-width="3" stroke-opacity="0.5" />
            <line x1="300" y1="320" x2="580" y2="250" stroke="#CBD5E0" stroke-width="1" stroke-dasharray="2 6" />
            <line x1="300" y1="100" x2="580" y2="280" stroke="#CBD5E0" stroke-width="1.5" />
            <line x1="300" y1="280" x2="580" y2="120" stroke="#CBD5E0" stroke-width="2" stroke-opacity="0.3" />

            <!-- Particles (Noise) -->
            <circle cx="350" cy="120" r="6" fill="#A0AEC0" />
            <circle cx="420" cy="90" r="12" fill="#E53E3E" opacity="0.6" /> <!-- Red accent -->
            <circle cx="480" cy="160" r="8" fill="#718096" />
            <circle cx="380" cy="200" r="16" fill="#0B192C" opacity="0.2" />
            <circle cx="520" cy="220" r="5" fill="#A0AEC0" />
            <circle cx="450" cy="280" r="10" fill="#0055A4" opacity="0.4" /> <!-- Blue accent -->
            <circle cx="330" cy="300" r="7" fill="#718096" />
            <circle cx="550" cy="100" r="14" fill="#CBD5E0" />
            <circle cx="500" cy="320" r="9" fill="#E53E3E" opacity="0.3" />
          </g>

          <!-- FUNNEL / CURATION LINES (Center) -->
          <g transform="translate(580, 0)">
            <!-- Converging lines into curation box -->
            <path d="M 0 150 C 60 150, 60 180, 120 180" fill="none" stroke="#A0AEC0" stroke-width="2" />
            <path d="M 0 180 C 60 180, 60 200, 120 200" fill="none" stroke="#A0AEC0" stroke-width="2" />
            <path d="M 0 200 C 60 200, 60 220, 120 220" fill="none" stroke="#A0AEC0" stroke-width="2" />
            <path d="M 0 250 C 60 250, 60 220, 120 220" fill="none" stroke="#A0AEC0" stroke-width="2" />

            <!-- Diverging lines out of curation box -->
            <path d="M 120 180 C 180 180, 180 160, 240 160" fill="none" stroke="#0055A4" stroke-width="3" />
            <path d="M 120 200 C 180 200, 180 200, 240 200" fill="none" stroke="#0055A4" stroke-width="3" />
            <path d="M 120 220 C 180 220, 180 240, 240 240" fill="none" stroke="#0055A4" stroke-width="3" />
          </g>

          <!-- SIGNAL (Right Side) - Ordered, clear, strong -->
          <g transform="translate(820, 0)">
            <!-- Lines -->
            <line x1="0" y1="160" x2="280" y2="160" stroke="#0055A4" stroke-width="3" />
            <line x1="0" y1="200" x2="280" y2="200" stroke="#0055A4" stroke-width="3" />
            <line x1="0" y1="240" x2="280" y2="240" stroke="#0055A4" stroke-width="3" />

            <!-- Particles (Signal) -->
            <circle cx="80" cy="160" r="10" fill="#0B192C" />
            <circle cx="180" cy="160" r="10" fill="#0B192C" />

            <circle cx="120" cy="200" r="12" fill="#0055A4" />
            <circle cx="240" cy="200" r="12" fill="#0055A4" />

            <circle cx="60" cy="240" r="8" fill="#E53E3E" />
            <circle cx="200" cy="240" r="8" fill="#E53E3E" />
          </g>
        </svg>

        <!-- Left Label: Noise -->
        <div class="label-group left">
          <div class="label-title">Noise</div>
          <div class="label-desc">High volume, variable quality, unverified authority.</div>
        </div>

        <!-- Center Box: Curation -->
        <div class="curation-box">
          <div class="curation-title">Curation</div>
          <div class="curation-desc">Appraisal<br>Context<br>Verification</div>
        </div>

        <!-- Right Label: Signal -->
        <div class="label-group right">
          <div class="label-title">Signal</div>
          <div class="label-desc">Durable clinical impact, vetted accuracy.</div>
        </div>

      </div>
    </div>

  </div>

</body>
</html>
```
